using Microsoft.EntityFrameworkCore;

class CosmosContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=key",
            "CatalogDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(b =>
        {
            b.ToContainer("Products");
            b.HasPartitionKey(p => p.Category);
            b.HasNoDiscriminator();
        });
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public string Category { get; set; } = default!;
}

using Microsoft.EntityFrameworkCore;

class CosmosQueryService
{
    // EF Core 9 removed sync Cosmos queries — all queries must be async.
    async Task<List<Product>> GetProductsByCategoryAsync(CosmosContext db, string category)
    {
        return await db.Products
            .Where(p => p.Category == category)
            .ToListAsync();
    }

    async Task<Product?> GetProductAsync(CosmosContext db, string id)
    {
        return await db.Products.FirstOrDefaultAsync(p => p.Id == id);
    }
}

